package com.voltsync.domain;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * Validation report generated by the independent PlanValidator.
 */
public record ValidationReport(boolean valid, List<ValidationViolation> violations) {

    public ValidationReport {
        violations = violations != null ? Collections.unmodifiableList(new ArrayList<>(violations)) : Collections.emptyList();
    }

    public static ValidationReport success() {
        return new ValidationReport(true, Collections.emptyList());
    }

    public static ValidationReport failed(List<ValidationViolation> violations) {
        return new ValidationReport(false, violations);
    }
}
